{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Erlotinib, the closest retrieved analogue (Morgan 0.2414), has absolute oral bioavailability of 59% (95% CI 55-63%) in healthy subjects; the query shares the anilino-heteroaromatic kinase-inhibitor motif, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Tramadol, which shares the methoxyphenyl and amino-alcohol/basic-amine features, has mean absolute oral bioavailability of 67.9% in adult volunteers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Simotinib, an anilinoquinazoline EGFR inhibitor structurally related to the query, was reported to have good oral bioavailability in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "A close analogue with a methoxyphenyl-piperidine-aminobenzimidazole scaffold had estimated absolute oral bioavailability of 3% in humans, providing contradictory evidence; however, its low F may reflect poor absorption/metabolism not clearly shared by the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "AZD5423, a methoxyphenyl-containing compound, has oral F ~3%, but this low value reflects its inhaled-drug design and first-pass metabolism, making it weakly transferable to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "Agomelatine has absolute F <5% due to extensive first-pass metabolism, but shares only the methoxyphenyl motif and is weakly transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high: the closest structural analogue erlotinib and multiple methoxyphenyl/amino-alcohol analogues show F ≥60%, while low-F analogues are less transferable because their low bioavailability is driven by first-pass metabolism or inhaled-drug design.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the exact query molecule.",
    "All retrieved analogues have low Morgan similarity (<0.25), limiting quantitative transferability.",
    "Uncertainty remains about the metabolic first-pass liability of the aniline and primary-amine motifs in the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

